#!/bin/bash
# Uninstall script for SiliconMotion InstantView
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling SiliconMotion InstantView..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping SiliconMotion InstantView if running..."
pkill -f "SiliconMotion InstantView" 2>/dev/null || true

# Kill application with bundle ID com.SMI-Inc.InstantView if running
echo "Stopping application with bundle ID com.SMI-Inc.InstantView if running..."
killall -9 "com.SMI-Inc.InstantView" 2>/dev/null || true

# Remove /Applications/macOS InstantView.app
echo "Removing /Applications/macOS InstantView.app..."
if [ -d "/Applications/macOS InstantView.app" ]; then
    rm -rf "/Applications/macOS InstantView.app" 2>/dev/null || true
elif [ -f "/Applications/macOS InstantView.app" ]; then
    rm -f "/Applications/macOS InstantView.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/InstantView
echo "Removing $HOME/Library/Application Support/InstantView..."
if [ -d "$HOME/Library/Application Support/InstantView" ]; then
    rm -rf "$HOME/Library/Application Support/InstantView" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/InstantView" ]; then
    rm -f "$HOME/Library/Application Support/InstantView" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/com.SMI-Inc.InstantView
echo "Removing $HOME/Library/Caches/com.SMI-Inc.InstantView..."
if [ -d "$HOME/Library/Caches/com.SMI-Inc.InstantView" ]; then
    rm -rf "$HOME/Library/Caches/com.SMI-Inc.InstantView" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/com.SMI-Inc.InstantView" ]; then
    rm -f "$HOME/Library/Caches/com.SMI-Inc.InstantView" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
